'use client';

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type JSX,
  type ReactElement,
  type ReactNode,
} from 'react';
import {
  Autocomplete,
  Collection,
  Dialog as RACDialog,
  Header,
  Input,
  ListBox,
  ListBoxItem,
  ListBoxSection,
  Modal,
  ModalOverlay,
  PopoverContext,
  SearchField,
  Text,
  composeRenderProps,
  useFilter,
  useSlottedContext,
  type Key,
  type ListBoxItemProps,
  type ListBoxSectionProps,
} from 'react-aria-components';
import { IconSearch } from '@tabler/icons-react';
import styles from './command.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/**
 * Overlays portal to <body>, outside any ThemeScope. At open time copy the scope attributes
 * (data-strata-theme/scheme/density) and dir/lang of the element the palette belongs to onto the overlay root.
 */
const SCOPE_ATTRS = ['data-strata-theme', 'data-strata-scheme', 'data-strata-density'] as const;
function mirrorScope(overlay: HTMLElement, source: Element | null | undefined): void {
  if (!source || overlay.contains(source)) return;
  for (const name of SCOPE_ATTRS) {
    // Look each attribute up on its own: a single-tenant app themes :root and scopes only the scheme.
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
  for (const name of ['dir', 'lang']) {
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
}

export interface CommandDialogProps<T> {
  /** Controlled open state. Omit inside a DialogTrigger. */
  isOpen?: boolean;
  /** Initial open state when uncontrolled. */
  defaultOpen?: boolean;
  /** Called when the palette opens or closes (Escape, backdrop click, or after an item's action). */
  onOpenChange?: (isOpen: boolean) => void;
  /** Placeholder of the search input. */
  placeholder?: string;
  /** Accessible name of the palette and its input. */
  'aria-label'?: string;
  /** Called with the chosen item's `id` (Enter or click). The palette closes afterwards. */
  onAction?: (key: Key) => void;
  /** CommandSection / CommandItem elements, or a function rendering one per entry of `items`. */
  children: ReactNode | ((item: T) => ReactElement);
  /** Entries for a dynamic collection. */
  items?: Iterable<T>;
  /** Decides whether an item matches the query. Defaults to a case- and accent-insensitive "contains". */
  filter?: (textValue: string, inputValue: string) => boolean;
  /** Content when nothing matches. Receives the current query. */
  renderEmptyState?: (inputValue: string) => ReactNode;
  /** Replaces the keyboard hint row; pass `null` to hide it. */
  footer?: ReactNode;
  /** Class for the palette panel. */
  className?: string;
  /** Style for the palette panel. */
  style?: CSSProperties;
}

/**
 * A ⌘K command palette: a modal search field that filters a list of commands or destinations as you type. Arrow
 * keys move through results, Enter runs the highlighted one, Escape clears the query and then closes.
 */
export function CommandDialog<T extends object>({
  isOpen,
  defaultOpen,
  onOpenChange,
  placeholder = 'Type a command or search…',
  'aria-label': ariaLabel = 'Command menu',
  onAction,
  children,
  items,
  filter,
  renderEmptyState,
  footer,
  className,
  style,
}: CommandDialogProps<T>): JSX.Element {
  const triggerRef = useSlottedContext(PopoverContext)?.triggerRef;
  const anchorRef = useRef<HTMLSpanElement>(null);
  const overlayRef = useCallback(
    (node: HTMLDivElement | null) => {
      if (node) mirrorScope(node, triggerRef?.current ?? anchorRef.current ?? document.activeElement);
    },
    [triggerRef],
  );

  return (
    <>
      {!triggerRef && <span ref={anchorRef} hidden />}
      <ModalOverlay
        ref={overlayRef}
        className={styles.overlay}
        isDismissable
        isOpen={isOpen}
        defaultOpen={defaultOpen}
        onOpenChange={onOpenChange}
      >
        <Modal className={cx(styles.panel, className)} style={style}>
          <RACDialog aria-label={ariaLabel} className={styles.dialog}>
            {({ close }) => (
              <CommandPalette<T>
                aria-label={ariaLabel}
                placeholder={placeholder}
                items={items}
                filter={filter}
                renderEmptyState={renderEmptyState}
                footer={footer}
                onAction={(key) => {
                  onAction?.(key);
                  close();
                }}
              >
                {children}
              </CommandPalette>
            )}
          </RACDialog>
        </Modal>
      </ModalOverlay>
    </>
  );
}

interface CommandPaletteProps<T>
  extends Pick<CommandDialogProps<T>, 'placeholder' | 'children' | 'items' | 'filter' | 'renderEmptyState' | 'footer'> {
  'aria-label': string;
  onAction: (key: Key) => void;
}

/** Lives inside the modal so the query resets every time the palette opens. */
function CommandPalette<T extends object>({
  'aria-label': ariaLabel,
  placeholder,
  children,
  items,
  filter,
  renderEmptyState,
  footer,
  onAction,
}: CommandPaletteProps<T>): JSX.Element {
  const [query, setQuery] = useState('');
  const { contains } = useFilter({ sensitivity: 'base' });

  return (
    <>
      <Autocomplete inputValue={query} onInputChange={setQuery} filter={filter ?? contains}>
        <SearchField aria-label={ariaLabel} autoFocus className={styles.search}>
          <IconSearch aria-hidden className={styles.searchIcon} size="1.125em" stroke={1.75} />
          {/* The combobox pattern (APG): focus stays here and aria-activedescendant points at the active option. It
              also tells assistive tech — and axe — that the scrolling results list is operated from this input. */}
          <Input placeholder={placeholder} role="combobox" aria-expanded className={styles.input} />
        </SearchField>
        <ListBox<T>
          aria-label={ariaLabel}
          items={items}
          onAction={onAction}
          className={styles.list}
          renderEmptyState={() =>
            renderEmptyState ? (
              renderEmptyState(query)
            ) : (
              <p className={styles.empty}>
                {query ? (
                  <>
                    No results for <span className={styles.query}>“{query}”</span>
                  </>
                ) : (
                  'No results'
                )}
              </p>
            )
          }
        >
          {children}
        </ListBox>
      </Autocomplete>
      {footer === undefined ? (
        <div className={styles.footer}>
          <span className={styles.hint}>
            <kbd className={styles.kbd}>↑</kbd>
            <kbd className={styles.kbd}>↓</kbd>
            to navigate
          </span>
          <span className={styles.hint}>
            <kbd className={styles.kbd}>↵</kbd>
            to select
          </span>
          <span className={styles.hint}>
            <kbd className={styles.kbd}>esc</kbd>
            to close
          </span>
        </div>
      ) : (
        footer
      )}
    </>
  );
}

export interface CommandSectionProps<T> extends ListBoxSectionProps<T> {
  /** Visible heading for the group, e.g. "Components". */
  title?: ReactNode;
}

/** A titled group of results. Hidden automatically when none of its items match. */
export function CommandSection<T extends object>({
  title,
  items,
  children,
  className,
  ...props
}: CommandSectionProps<T>): JSX.Element {
  return (
    <ListBoxSection<T> {...props} className={cx(styles.section, className)}>
      {title != null && <Header className={styles.sectionTitle}>{title}</Header>}
      {typeof children === 'function' ? <Collection items={items}>{children}</Collection> : children}
    </ListBoxSection>
  );
}

export interface CommandItemProps<T = object> extends Omit<ListBoxItemProps<T>, 'children'> {
  /** The result's label. */
  children: ReactNode;
  /** Text matched against the query. Required when `children` isn't a plain string; add keywords here too. */
  textValue?: string;
  /** Leading icon. Decorative. */
  icon?: ReactNode;
  /** Secondary line under the label. */
  description?: ReactNode;
  /** Short trailing text at the inline end, e.g. a category or shortcut. */
  meta?: ReactNode;
}

/** One result in a CommandDialog. */
export function CommandItem<T extends object>({
  children,
  textValue,
  icon,
  description,
  meta,
  className,
  ...props
}: CommandItemProps<T>): JSX.Element {
  return (
    <ListBoxItem<T>
      {...props}
      textValue={textValue ?? (typeof children === 'string' ? children : undefined)}
      className={composeRenderProps(className, (c) => cx(styles.item, c))}
    >
      {icon != null && (
        <span className={styles.icon} aria-hidden>
          {icon}
        </span>
      )}
      <span className={styles.text}>
        <Text slot="label" className={styles.label}>
          {children}
        </Text>
        {description != null && (
          <Text slot="description" className={styles.description}>
            {description}
          </Text>
        )}
      </span>
      {meta != null && <span className={styles.meta}>{meta}</span>}
    </ListBoxItem>
  );
}

/**
 * Calls `onOpen` when the user presses ⌘K (macOS) or Ctrl+K (elsewhere), anywhere on the page. Pass a different
 * `key` to bind another letter, or `isDisabled` to unbind. Skips key presses an earlier listener already handled
 * (`preventDefault()`), so two palettes on one page don't both open.
 */
export function useCommandShortcut(
  onOpen: () => void,
  { key = 'k', isDisabled = false }: { key?: string; isDisabled?: boolean } = {},
): void {
  const handler = useRef(onOpen);
  useEffect(() => {
    handler.current = onOpen;
  });
  useEffect(() => {
    if (isDisabled) return;
    const onKeyDown = (e: KeyboardEvent) => {
      // A handler that ran earlier (e.g. the app's own search) already claimed the shortcut.
      if (e.defaultPrevented) return;
      if (e.key?.toLowerCase() === key.toLowerCase() && (e.metaKey || e.ctrlKey) && !e.altKey && !e.shiftKey) {
        e.preventDefault();
        handler.current();
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [key, isDisabled]);
}

/* Backdrop. Portalled to <body>, so it re-applies the ThemeScope base (font, colour, box model). */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  align-items: center;
  box-sizing: border-box;
  padding: min(12dvh, calc(var(--strata-space-16) * 2)) var(--strata-space-4) var(--strata-space-4);
  /* Dim what's behind by a fixed amount. A colour tint can't do this in both schemes: every surface token is
     already near the page colour in dark schemes, and light-dark() gets mangled by Lightning CSS pipelines. */
  -webkit-backdrop-filter: brightness(0.55);
  backdrop-filter: brightness(0.55);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-default);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.overlay *,
.overlay *::before,
.overlay *::after {
  box-sizing: border-box;
}

.panel {
  display: flex;
  flex-direction: column;
  inline-size: 100%;
  max-inline-size: calc(var(--strata-space-16) * 9);
  max-block-size: 100%;
  overflow: hidden;
  background: var(--strata-color-surface-raised);
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-container);
  box-shadow: var(--strata-shadow-overlay);
  outline: none;
}

.dialog {
  display: flex;
  flex-direction: column;
  min-block-size: 0;
  outline: none;
}
/* Programmatic focus on open. Pseudo-class selector so page-level `[tabindex]:focus-visible` rules can't outrank it. */
.dialog:focus-visible {
  outline: none;
}

/* Search row: no box, just a hairline underneath. */
.search {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--strata-space-2);
  min-block-size: calc(var(--strata-control-height) + var(--strata-space-2));
  padding-inline: var(--strata-space-4);
  border-block-end: 1px solid var(--strata-color-border-subtle);
}
/* Focus indicator: the input is flat, so the hairline under it thickens to a 2px focus-ring line while the input has
   focus (it always does while the palette is open; it goes away if focus moves to the panel). */
.search:focus-within {
  border-block-end-color: var(--strata-color-focus-ring);
  box-shadow: inset 0 -1px 0 var(--strata-color-focus-ring);
}
.searchIcon {
  flex: none;
  color: var(--strata-color-text-subtle);
}
.input {
  flex: 1 1 auto;
  min-inline-size: 0;
  block-size: 100%;
  padding: 0;
  margin: 0;
  border: 0;
  background: transparent;
  color: var(--strata-color-text-default);
  font: inherit;
  font-size: var(--strata-font-size-md);
  outline: none;
  appearance: none;
}
/* The search row's underline is the focus indicator (see .search:focus-within). */
.input:focus-visible {
  outline: none;
}
.input::placeholder {
  color: var(--strata-color-text-subtle);
  opacity: 1;
}
.input::-webkit-search-cancel-button,
.input::-webkit-search-decoration {
  appearance: none;
}

.list {
  flex: 1 1 auto;
  min-block-size: 0;
  max-block-size: min(calc(var(--strata-space-16) * 5), 60dvh);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--strata-space-1);
  scroll-padding-block: var(--strata-space-1);
  outline: none;
}

.section:not(:first-child) {
  margin-block-start: var(--strata-space-1);
}
.sectionTitle {
  padding: var(--strata-space-2) var(--strata-space-2) var(--strata-space-1);
  font-size: var(--strata-font-size-xs);
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-subtle);
}

.item {
  display: flex;
  align-items: center;
  gap: var(--strata-space-3);
  min-block-size: var(--strata-control-height);
  padding: var(--strata-space-1) var(--strata-space-2);
  border-radius: min(var(--strata-radius-button), var(--strata-space-2));
  color: var(--strata-color-text-default);
  line-height: var(--strata-line-height-snug);
  text-decoration: none;
  cursor: default;
  user-select: none;
  outline: none;
}
.item[data-focused] {
  background: color-mix(in oklab, var(--strata-color-text-default) 7%, transparent);
}
.item[data-pressed] {
  background: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}
.item[data-disabled] {
  color: var(--strata-color-text-disabled);
  pointer-events: none;
}
.icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  inline-size: 1.125em;
  block-size: 1.125em;
  color: var(--strata-color-text-subtle);
}
.icon svg {
  inline-size: 100%;
  block-size: 100%;
}
.item[data-focused] .icon {
  color: var(--strata-color-text-default);
}
.text {
  display: grid;
  flex: 1 1 auto;
  min-inline-size: 0;
}
.label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--strata-font-size-xs);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-subtle);
}
.meta {
  flex: none;
  margin-inline-start: auto;
  font-size: var(--strata-font-size-xs);
  color: var(--strata-color-text-subtle);
  font-variant-numeric: tabular-nums;
}

.empty {
  margin: 0;
  padding: var(--strata-space-8) var(--strata-space-4);
  text-align: center;
  font-size: var(--strata-font-size-sm);
  color: var(--strata-color-text-subtle);
}
.query {
  color: var(--strata-color-text-default);
  overflow-wrap: anywhere;
}

.footer {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--strata-space-2) var(--strata-space-4);
  padding: var(--strata-space-2) var(--strata-space-4);
  border-block-start: 1px solid var(--strata-color-border-subtle);
  font-size: var(--strata-font-size-xs);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-subtle);
}
.hint {
  display: inline-flex;
  align-items: center;
  gap: var(--strata-space-1);
}
.kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--strata-space-5);
  block-size: var(--strata-space-5);
  padding-inline: var(--strata-space-1);
  border: 1px solid var(--strata-color-border-default);
  border-radius: min(var(--strata-radius-badge), var(--strata-space-1));
  background: var(--strata-color-surface-sunken);
  box-shadow: inset 0 -1px 0 var(--strata-color-border-default);
  color: var(--strata-color-text-subtle);
  font-family: var(--strata-font-mono);
  font-size: var(--strata-font-size-xs);
  font-weight: var(--strata-font-weight-medium);
  line-height: 1;
}

@media (prefers-reduced-motion: no-preference) {
  .overlay[data-entering] {
    animation: fade var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
  .overlay[data-exiting] {
    animation: fade var(--strata-motion-duration-fast) var(--strata-motion-easing) reverse;
  }
  .panel[data-entering] {
    animation: zoom var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
  .panel[data-exiting] {
    animation: zoom var(--strata-motion-duration-fast) var(--strata-motion-easing) reverse;
  }
}

@keyframes fade {
  from {
    opacity: 0;
  }
}
@keyframes zoom {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
